-- CityOps demo data: districts and citizen service requests.
-- All data is synthetic and reproducible (fixed seeds).

CREATE EXTENSION IF NOT EXISTS postgis;

-- ---------------------------------------------------------------- districts
-- 21 real districts (qism) of central Cairo. Boundaries: CAPMAS / OCHA ROMENA via geoBoundaries
-- (gbOpen EGY ADM2, CC BY 3.0 IGO), simplified to ~15 m with ST_SimplifyPreserveTopology.
-- The source sits ~120 m east and ~28 m north of OpenStreetMap. A shift fitted against OSM's
-- Zamalek and Roda islands and Heliopolis raises their overlap from 0.63-0.91 to 0.95 (IoU),
-- so the boundaries line up with the streets and the Nile on the basemap.
CREATE TABLE districts (
    id      serial PRIMARY KEY,
    name    text NOT NULL,
    name_ar text NOT NULL,
    geom    geometry(MultiPolygon, 4326) NOT NULL
);

