CREATE INDEX districts_geom_idx ON districts USING gist (geom);

-- --------------------------------------------------------- service requests
CREATE TABLE service_requests (
    id          serial PRIMARY KEY,
    category    text NOT NULL CHECK (category IN ('road', 'water', 'lighting', 'waste')),
    status      text NOT NULL CHECK (status IN ('new', 'in_review', 'approved', 'rejected')),
    priority    text NOT NULL CHECK (priority IN ('low', 'normal', 'high')),
    description text,
    created_at  timestamptz NOT NULL,
    updated_at  timestamptz NOT NULL,
    geom        geometry(Point, 4326) NOT NULL
);

CREATE INDEX service_requests_geom_idx   ON service_requests USING gist (geom);
CREATE INDEX service_requests_status_idx ON service_requests (status);
CREATE INDEX service_requests_created_idx ON service_requests (created_at);

-- GeoServer WFS-T sends NULL (or '' for text) for every attribute the client leaves out, and the
-- Unix epoch (1970-01-01) for an omitted timestamp, so column DEFAULTs never fire. This trigger
-- applies the defaults and stamps updates.
CREATE FUNCTION service_requests_defaults() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.status     := coalesce(nullif(NEW.status, ''), 'new');
        NEW.priority   := coalesce(nullif(NEW.priority, ''), 'normal');
        IF NEW.created_at IS NULL OR NEW.created_at < '2000-01-01' THEN
            NEW.created_at := now();
        END IF;
    END IF;
    NEW.updated_at := now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER service_requests_defaults_trg
BEFORE INSERT OR UPDATE ON service_requests
FOR EACH ROW EXECUTE FUNCTION service_requests_defaults();

SELECT setseed(0.42);

INSERT INTO service_requests (category, status, priority, description, created_at, geom)
SELECT cat,
       (ARRAY['new', 'in_review', 'approved', 'rejected', 'approved', 'new'])[1 + floor(random() * 6)::int],
       (ARRAY['low', 'normal', 'normal', 'high'])[1 + floor(random() * 4)::int],
       CASE cat
         WHEN 'road'     THEN (ARRAY['Pothole near junction', 'Damaged kerb', 'Faded road markings', 'Blocked drain on road'])[1 + floor(random() * 4)::int]
         WHEN 'water'    THEN (ARRAY['Pipe leak on pavement', 'Low water pressure', 'Water meter fault', 'Sewer overflow'])[1 + floor(random() * 4)::int]
         WHEN 'lighting' THEN (ARRAY['Street light out', 'Flickering lamp post', 'Damaged light pole', 'Light on during day'])[1 + floor(random() * 4)::int]
         ELSE                 (ARRAY['Missed bin collection', 'Illegal dumping', 'Overflowing container', 'Bulky waste pickup'])[1 + floor(random() * 4)::int]
       END,
       now() - (random() * interval '90 days'),
       geom
FROM (
    SELECT (ARRAY['road', 'water', 'lighting', 'waste'])[1 + floor(random() * 4)::int] AS cat,
           (dp).geom AS geom
    FROM (SELECT ST_Dump(ST_GeneratePoints(geom, 8 + (id * 7) % 23, id)) AS dp FROM districts) AS pts
) AS s;

-- ------------------------------------------------------------- district stats
-- Live spatial join for the choropleth: recalculated on every request, so edits show up at once.
CREATE VIEW district_stats AS
SELECT d.id,
       d.name,
       d.name_ar,
       count(r.id) FILTER (WHERE r.status IN ('new', 'in_review')) AS open_requests,
       count(r.id) FILTER (WHERE r.status = 'approved')            AS approved_requests,
       count(r.id)                                                 AS total_requests,
       d.geom
FROM districts d
LEFT JOIN (
    -- Each request counts in one district. Neighbouring outlines overlap by slivers after
    -- simplification; a point in a sliver goes to the district with the lowest id.
    SELECT DISTINCT ON (r.id) r.id, r.status, dd.id AS district_id
    FROM service_requests r
    JOIN districts dd ON ST_Contains(dd.geom, r.geom)
    ORDER BY r.id, dd.id
) r ON r.district_id = d.id
GROUP BY d.id, d.name, d.name_ar, d.geom;
